use vstd::prelude::*;

verus! {

    // Specification helpers for character classes
    spec fn is_upper(c: char) -> bool {
        'A' <= c && c <= 'Z'
    }

    spec fn is_lower(c: char) -> bool {
        'a' <= c && c <= 'z'
    }

    // Builds the 4-character result "A<ch>C\n"
    fn build_result(ch: char) -> Vec<char>
        requires
            is_upper(ch),
        ensures
            |res: &Vec<char>| res.len() == 4
                && res[0] == 'A'
                && res[1] == ch
                && res[2] == 'C'
                && res[3] == '\n'
    {
        let mut v: Vec<char> = Vec::new();
        v.push('A');
        v.push(ch);
        v.push('C');
        v.push('\n');
        v
    }

    fn solve(input: Vec<char>) -> Vec<char>
        requires
            // Minimum length: "AtCoder " + Name(at least 1 char) + " Contest\n" = 8 + 1 + 8 = 17,
            // but problem says at least 18, and last is '\n'.
            input.len() >= 18,
            input[input.len() - 1] == '\n',
            // Prefix "AtCoder "
            input[0] == 'A',
            input[1] == 't',
            input[2] == 'C',
            input[3] == 'o',
            input[4] == 'd',
            input[5] == 'e',
            input[6] == 'r',
            input[7] == ' ',
        ensures
            // The result is exactly "A<initial>C\n"
            |res: &Vec<char>| res.len() == 4
                && res[0] == 'A'
                && is_upper(res[1])
                && res[2] == 'C'
                && res[3] == '\n'
    {
        // The name starts at index 8
        let name_start: usize = 8;
        // The first character of the name must be uppercase
        assert(is_upper(input[name_start]));
        let initial: char = input[name_start];

        // Scan the rest of the name until the next space
        let mut idx: usize = name_start + 1;
        while idx < input.len() && input[idx] != ' '
            invariant
                name_start + 1 <= idx && idx <= input.len(),
                // all characters from name_start+1 up to idx are lowercase
                forall |j: usize| (name_start + 1 <= j && j < idx) ==> is_lower(input[j]),
            decreases input.len() - idx
        {
            // each scanned character must be lowercase
            assert(is_lower(input[idx]));
            idx += 1;
        }

        // We must have stopped at a space (not at end of buffer)
        assert(idx < input.len());
        assert(input[idx] == ' ');

        // After that space, the exact word "Contest" must appear
        let contest_start: usize = idx + 1;
        let contest: [char; 7] = ['C','o','n','t','e','s','t'];
        let mut i: usize = 0;
        while i < 7
            invariant 0 <= i && i <= 7,
            decreases 7 - i
        {
            assert(input[contest_start + i] == contest[i]);
            i += 1;
        }

        // Ensure that "Contest" is immediately followed by the final newline
        assert(contest_start + 7 == input.len() - 1);

        // Build and return the 4-character abbreviation
        build_result(initial)
    }
}

